 var invalid = Json(await controller.Import(new() { Items = [new() { Name = "A", Phone = "0900000001" }, new() { Name = "", Phone = "0900000002" }], Preview = false }));
 Check(!invalid.GetProperty("valid").GetBoolean() && await db.Customers.CountAsync() == 1, "Import with errors writes no partial customers"); Clear();
 var imported = Json(await controller.Import(new() { Items = Enumerable.Range(1,20).Select(i => new CreateCustomerDto { Name = "Imported " + i, Phone = "091" + i.ToString("D7") }).ToList(), Preview = false })); Clear();
 Check(imported.GetProperty("valid").GetBoolean() && await db.Customers.CountAsync() == 21, "Valid import adds all rows");
 var list = Json(await controller.List(page:2));
