 Check(Json(await controller.Search()).GetArrayLength() == 10, "POS search limited separately from management");
 await controller.Status(id, new() { IsActive = false }); Clear();
 Check(Json(await controller.Search("Lan")).GetArrayLength() == 0 && Json(await controller.List(active:false)).GetProperty("total").GetInt32() == 1, "Inactive customers kept but absent in POS");
 var category = new FoodCategory { Name = "Coffee" }; var food = new Food { Name = "Coffee", Category = category, Price = 20000 }; db.Add(food); await db.SaveChangesAsync();
 async Task<int> NewBill() { var b = await invoices.Takeaway(new() { RequestKey = Guid.NewGuid().ToString() }, "test"); await order.Add(new() { IdBill = b, IdFood = food.Id, Count = 1 }); await order.Send(b); Clear(); return b; }
