 Check(await checkout.Checkout(first, new() { IdCustomer = id }) is OkObjectResult, "Checkout associates active customer"); Clear();
 Check((await db.Customers.FindAsync(id))!.Points == 2 && (await db.Bills.FindAsync(first))!.PointsEarned == 2, "Real paid amount earns floor points");
 Check(await checkout.Checkout(first, new() { IdCustomer = id }) is NotFoundObjectResult && await db.CustomerPointEntries.CountAsync() == 1, "Repeated checkout cannot credit points twice"); Clear();
 var second = await NewBill();
 Check(await checkout.Checkout(second, new() { RedeemPoints = 1 }) is BadRequestObjectResult, "Guest cannot redeem points"); Clear();
