 Check(await checkout.Checkout(second, new() { IdCustomer = id, RedeemPoints = 3 }) is BadRequestObjectResult, "Overspending points rejected"); Clear();
 await checkout.Checkout(second, new() { IdCustomer = id, RedeemPoints = 2 }); Clear();
 Check((await db.Bills.FindAsync(second))!.TotalPrice == 19800 && (await db.Customers.FindAsync(id))!.Points == 1, "Point discount applies before earning new points");
 Check(await db.CashEntries.Where(c => c.IdBill == second).SumAsync(c => c.Amount) == 19800, "Cashbook receives only actual payment");
 Check(Json(await controller.Detail(id)).GetProperty("netSpend").GetDecimal() == 39800, "Customer spend matches discounted real receipts");
 await controller.Update(id, new() { Name = "Lan renamed", Phone = "0901234567" }); Clear();
 Check(Json(await new OrdersController(db).Detail(first)).GetProperty("CustomerName").GetString() == "Lan demo", "Paid customer snapshot survives renaming");
 await invoices.Refund(first, new() { Reason = "Refund demo" }, "test"); Clear();
 Check((await db.Customers.FindAsync(id))!.Points == -1, "Refund removes already spent earned points with visible negative balance");
 await invoices.Refund(first, new() { Reason = "Retry" }, "test"); Clear();
 Check(await db.CustomerPointEntries.CountAsync(e => e.IdBill == first && e.Kind == "Refund") == 1 && (await db.Customers.FindAsync(id))!.Points == -1, "Refund retry cannot remove points twice");
 await invoices.Refund(second, new() { Reason = "Refund second" }, "test"); Clear();
 Check((await db.Customers.FindAsync(id))!.Points == 0, "Refund restores redeemed points and removes awarded points exactly");
 var details = Json(await controller.Detail(id));
 Check(details.GetProperty("netSpend").GetDecimal() == 0 && details.GetProperty("refundAmount").GetDecimal() == 39800 && details.GetProperty("visits").GetInt32() == 0 && details.GetProperty("points").GetArrayLength() == 5, "Customer history retains refunds and point ledger");
 var c = (await db.Customers.FindAsync(id))!; c.Points = 200; await db.SaveChangesAsync(); Clear();
 var free = await NewBill(); await checkout.Checkout(free, new() { IdCustomer = id, RedeemPoints = 200 }); Clear();
 var paid = (await db.Bills.Include(b => b.BillInfos).ThenInclude(i => i.Food).SingleAsync(b => b.Id == free));
 Check(paid.HasRecordedPayment && paid.TotalPrice == 0 && !DashboardCalculator.IsEstimated(paid) && DashboardCalculator.NetRevenue(paid) == 0, "Full point redemption is recorded zero payment not invented estimated revenue");
 Check(Json(await new OrdersController(db).List(status:1)).GetProperty("revenue").GetDecimal() == 0, "Order summary excludes point discounts and handles zero receipt");
 Check(!Json(await new OrdersController(db).Detail(free)).GetProperty("Estimated").GetBoolean(), "Full point payment remains refundable");
 Check(Json(await new CashbookController(db).Get(DateTime.Today,DateTime.Today)).GetProperty("Rows").EnumerateArray().All(e => e.GetProperty("Reference").GetString() != $"HD{free:D6}"), "Zero point receipt does not invent a legacy cashbook row");
 var report = Json(await new ReportController(db).GetRevenueReport(DateTime.Today,DateTime.Today.AddDays(1)));
 Check(report[0].GetProperty("TotalRevenue").GetDecimal() == 0, "Revenue report uses actual payment after point redemption");
 await invoices.Refund(free,new() { Reason = "Restore points" },"test"); Clear();
 Check((await db.Customers.FindAsync(id))!.Points == 200 && await db.CashEntries.CountAsync(e => e.IdBill == free) == 0, "Zero cash refund returns points without false cash entries");
 Check(Json(await controller.Detail(id,pointPage:2)).GetProperty("points").GetArrayLength() == 0, "Point ledger pagination bounded");
 var concurrentCustomer = new Customer { Name = "Concurrency demo", Phone = "0999999988", Points = 50 }; var cheap = new Food { Name = "Small coffee", IdCategory = category.Id, Price = 5000 };
 db.AddRange(concurrentCustomer,cheap); await db.SaveChangesAsync();
 var one = new Bill { OrderType = "Takeaway", BillInfos = [new() { Food = cheap, Count = 1, SentCount = 1, UnitPrice = 5000 }] };
 var two = new Bill { OrderType = "Takeaway", BillInfos = [new() { Food = cheap, Count = 1, SentCount = 1, UnitPrice = 5000 }] };
 db.AddRange(one,two); await db.SaveChangesAsync(); Clear();
 async Task<IActionResult> Pay(int billId) { await using var other = new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlServer(cs.ConnectionString).Options); return await new BillController(other).Checkout(billId,new() { IdCustomer = concurrentCustomer.Id, RedeemPoints = 50 }); }
 var simultaneous = await Task.WhenAll(Pay(one.Id),Pay(two.Id)); Clear();
 Check(simultaneous.Count(r => r is OkObjectResult) == 1 && simultaneous.Count(r => r is BadRequestObjectResult) == 1, "Concurrent orders cannot both spend the same point balance");
 Check((await db.Customers.FindAsync(concurrentCustomer.Id))!.Points == 0 && await db.CustomerPointEntries.CountAsync(e => e.IdCustomer == concurrentCustomer.Id && e.Kind == "Redeem") == 1, "Concurrent redemption records exactly one deduction");
 Console.WriteLine($"All {checks} customer checks passed.");
} finally { await db.Database.EnsureDeletedAsync(); }
